package com.nexus.property.property;
import com.nexus.property.core.*;import java.util.*;public final class PropertyMapper{private PropertyMapper(){} public static Map<String,Object> map(Map<String,Object>r){var m=new LinkedHashMap<String,Object>();m.put("id",Rows.s(r,"id"));m.put("ownerId",Rows.s(r,"owner_id"));m.put("ownerName",Rows.s(r,"owner_name"));m.put("ownerEmail",Rows.s(r,"owner_email"));m.put("ownerPhone",Rows.s(r,"owner_phone"));m.put("title",Rows.s(r,"title"));m.put("description",Rows.s(r,"description"));m.put("propertyType",Rows.s(r,"property_type"));m.put("location",Rows.s(r,"location"));m.put("price",Rows.d(r,"price"));m.put("bedrooms",Rows.l(r,"bedrooms"));m.put("bathrooms",Rows.l(r,"bathrooms"));m.put("area",Rows.d(r,"area"));m.put("amenities",Rows.jsonList(r.get("amenities")));m.put("status",Rows.s(r,"status"));String img=Rows.s(r,"primary_image");if(img!=null)m.put("primaryImage",img);Object av=r.get("avg_score");m.put("averageRating",av instanceof Number n?Math.round(n.doubleValue()*10.0)/10.0:0);m.put("ratingCount",Rows.l(r,"rating_count"));m.put("createdAt",Rows.l(r,"created_at"));m.put("updatedAt",Rows.l(r,"updated_at"));return m;}}
